package main

import (
	"os"
	"path/filepath"
	"testing"
)

// TestWithinRoot is the AC-4 path-traversal guard contract test (seam S7). Every
// escape vector — a symlink out of root, a ".." segment, an absolute path to
// another tree, a nested-symlink chain, a nonexistent path — MUST be rejected.
// Only root itself and genuine descendants (including a symlink that stays inside
// root) are accepted. This is security-critical: an escaping path is never
// ffprobed, read, or persisted.
func TestWithinRoot(t *testing.T) {
	// withinRoot's precondition: root is a resolved absolute path (resolveRoot
	// canonicalizes it in production). Canonicalize the temp dir to match — on
	// macOS t.TempDir() returns a /var/... path that symlinks to /private/var/...
	rawRoot := t.TempDir()
	root, err := filepath.EvalSymlinks(rawRoot)
	if err != nil {
		t.Fatalf("canonicalize root: %v", err)
	}

	inside := filepath.Join(root, "inside")
	if err := os.MkdirAll(inside, 0o755); err != nil {
		t.Fatal(err)
	}
	goodFile := filepath.Join(inside, "file.mkv")
	if err := os.WriteFile(goodFile, []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}

	// A sibling tree OUTSIDE root (absolute-path-injection target).
	outside := t.TempDir()
	outsideFile := filepath.Join(outside, "secret.mkv")
	if err := os.WriteFile(outsideFile, []byte("y"), 0o644); err != nil {
		t.Fatal(err)
	}

	// Symlink that escapes root -> /etc/passwd.
	escapeLink := filepath.Join(root, "escape.mkv")
	if err := os.Symlink("/etc/passwd", escapeLink); err != nil {
		t.Fatal(err)
	}
	// Symlink that stays inside root -> goodFile.
	validLink := filepath.Join(root, "link.mkv")
	if err := os.Symlink(goodFile, validLink); err != nil {
		t.Fatal(err)
	}
	// Nested symlink chain: chain.mkv -> escapeLink -> /etc/passwd.
	chainLink := filepath.Join(root, "chain.mkv")
	if err := os.Symlink(escapeLink, chainLink); err != nil {
		t.Fatal(err)
	}

	// ".." escape resolving to the sibling tree (lexical, pre-symlink check).
	dotdot := filepath.Join(root, "..", filepath.Base(outside), "secret.mkv")

	tests := []struct {
		name string
		cand string
		want bool
	}{
		{"root itself", root, true},
		{"file inside root", goodFile, true},
		{"symlink that stays inside root", validLink, true},
		{"dotdot escape", dotdot, false},
		{"absolute path to another tree", outsideFile, false},
		{"symlink escaping root", escapeLink, false},
		{"nested symlink chain escaping root", chainLink, false},
		{"nonexistent path", filepath.Join(root, "nope.mkv"), false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := withinRoot(root, tc.cand); got != tc.want {
				t.Fatalf("withinRoot(root, %q) = %v, want %v", tc.cand, got, tc.want)
			}
		})
	}
}
